 const c=$('canvas');c.onpointerdown=e=>{if(busy)return;const r=c.getBoundingClientRect(),p=printPoint(viewGeometry,(e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height);if(p.inside&&!panel()&&!$('editPlacement').hidden){$('editPlacement').click();return;}const hit=designAtPoint(panel()?.layers||[],area(),layerArtwork,p);if(hit<0)return;selectDesign(hit);gesture={x:e.clientX,y:e.clientY,original:{...layer()},width:r.width*viewGeometry.print.width/viewGeometry.width,height:r.height*viewGeometry.print.height/viewGeometry.height};c.setPointerCapture(e.pointerId);};c.onpointermove=e=>{if(!gesture)return;edit(()=>{layer().x=Math.max(0,Math.min(1,gesture.original.x+(e.clientX-gesture.x)/gesture.width));layer().y=Math.max(0,Math.min(1,gesture.original.y+(e.clientY-gesture.y)/gesture.height));});};c.onpointerup=c.onpointercancel=()=>{gesture=null;};c.onkeydown=e=>{if(busy)return;if(e.key==='Delete'||e.key==='Backspace'){if(layer()){e.preventDefault();$('remove').click();}return;}const delta={ArrowLeft:[-.005,0],ArrowRight:[.005,0],ArrowUp:[0,-.005],ArrowDown:[0,.005]}[e.key];if(!delta||!layer())return;e.preventDefault();edit(()=>{layer().x=Math.max(0,Math.min(1,layer().x+delta[0]*(e.shiftKey?10:1)));layer().y=Math.max(0,Math.min(1,layer().y+delta[1]*(e.shiftKey?10:1)));});};
 window.addEventListener('beforeunload',e=>{if(dirty){retainBrowserCopy();e.preventDefault();e.returnValue='';}});open().catch(e=>message(e.message));
